void can_irq_service_bus_off (Can_Dev can_dev)
{
  if ((can_dev->io_base [CANGSR] & ((UInt32) 1 << 7)))
    {
	  can_ctl_reset (can_dev) ;
	  
	  if(can_irq_func)
	    {
	      can_irq_func (can_dev->can_dev_id, CAN_IRQ_BUS_OFF) ;
		}
    }
}

